func (c *Consumer) HandleBatch(ctx context.Context, batch []Message) error {
    var workers sync.WaitGroup
    for _, message := range batch {
        workers.Add(1)
        go func(message Message) {
            defer workers.Done()
            for attempt := 0; attempt < 3; attempt++ {
                if err := c.processor.ApplyRemote(ctx, message); err != nil {
                    continue
                }
                _ = c.broker.CommitOffset(ctx, message.Partition, message.Offset)
                return
            }
        }(message)
    }
    workers.Wait()
    return nil
}

